-- Genset areas + 3 gensets with WEEKLY checklists (SQLite/D1 version of add_gensets.sql). Re-runnable.
INSERT OR IGNORE INTO areas (area_id, area_name, plant_id, status) SELECT 'A-GENSET-P1', 'Genset P1', COALESCE((SELECT plant_id FROM areas WHERE area_name = 'Chiller Room P1' LIMIT 1), (SELECT plant_id FROM areas WHERE area_name LIKE '%P1' LIMIT 1)), 'Active' WHERE NOT EXISTS (SELECT 1 FROM areas WHERE area_name = 'Genset P1');
INSERT OR IGNORE INTO areas (area_id, area_name, plant_id, status) SELECT 'A-GENSET-P2', 'Genset P2', COALESCE((SELECT plant_id FROM areas WHERE area_name = 'MSB LV Room P2' LIMIT 1), (SELECT plant_id FROM areas WHERE area_name LIKE '%P2' LIMIT 1)), 'Active' WHERE NOT EXISTS (SELECT 1 FROM areas WHERE area_name = 'Genset P2');
DELETE FROM checklist_templates WHERE equipment_id = (SELECT id FROM equipment WHERE equip_id = 'GENSET-P1-01');
DELETE FROM checklist_templates WHERE equipment_id = (SELECT id FROM equipment WHERE equip_id = 'GENSET-P2-01');
DELETE FROM checklist_templates WHERE equipment_id = (SELECT id FROM equipment WHERE equip_id = 'GENSET-P2-02');
